    wyniki.push("Priorytet wysoki");
    break;
}

console.log(wyniki); // ['Priorytet niski', 'Priorytet sredni'] - BLEDNIE oba

function dzienTygodniaNumer(nazwa) {
  switch (nazwa) {
    case "poniedzialek": return 1;
    case "wtorek": return 2;
    case "sroda": return 3;
    case "czwartek": return 4;
    case "piatek": return 5;
    case "sobota": return 6;
    case "niedziela": return 7;
    default: return -1;
  }
}

console.log(dzienTygodniaNumer("sroda")); // 3

function kategoriaWiekowa(wiek) {
  switch (true) {
    case wiek < 13:
      return "dziecko";
    case wiek < 20:
      return "nastolatek";
    default:
      return "dorosly";
  }
}

console.log(kategoriaWiekowa(10)); // "dziecko"
console.log(kategoriaWiekowa(15)); // "nastolatek"
console.log(kategoriaWiekowa(30)); // "dorosly"

const KODY_HTTP = { 200: "OK", 404: "Nie znaleziono", 500: "Blad serwera" };

function opisKodu(kod) {
  return KODY_HTTP[kod] ?? "Nieznany kod";
}

console.log(opisKodu(404)); // "Nie znaleziono"
console.log(opisKodu(301)); // "Nieznany kod"

function obsluzAkcje(typ, payload) {
  switch (typ) {
    case "DODAJ":
      return `Dodano: ${payload}`;
    case "USUN":
      return `Usunieto: ${payload}`;
    default:
      return "Nieznana akcja";
  }
}

console.log(obsluzAkcje("DODAJ", "produkt")); // "Dodano: produkt"

const WALIDATORY = {
  email: (w) => w.includes("@"),
  telefon: (w) => w.length === 9
};

function waliduj(typ, wartosc) {
  return WALIDATORY[typ](wartosc);
}

console.log(waliduj("email", "jan@test.pl")); // true
console.log(waliduj("telefon", "123456789"));  // true
console.log(waliduj("telefon", "123"));        // false

function ocenKierunekKompasu(stopnie) {
  switch (true) {
    case stopnie < 90:
      return "N";
    case stopnie < 180:
      return "E";
    case stopnie < 270:
      return "S";
    default:
      return "W";
  }
}

console.log(ocenKierunekKompasu(45));  // "N"
console.log(ocenKierunekKompasu(200)); // "S"

function formatujRozmiarPliku(jednostka) {
  switch (jednostka) {
    case "B":
    case "b":
      return "bajty";
    case "KB":
    case "kb":
      return "kilobajty";
    default:
      return "nieznana jednostka";
  }
}

console.log(formatujRozmiarPliku("b"));  // "bajty"
console.log(formatujRozmiarPliku("KB")); // "kilobajty"

const ETYKIETY_NASTROJU = { szczesliwy: "radosc", smutny: "smutek", zly: "zlosc" };
const nastroje = ["szczesliwy", "zly"];
const etykiety = nastroje.map(n => ETYKIETY_NASTROJU[n] ?? "nieznany");
console.log(etykiety); // ['radosc', 'zlosc']

function pobierzRozmiarKoszulki(numer) {
  switch (numer) {
    case 1: return "S";
    case 2: return "M";
    case 3: return "L";
    case 4: return "XL";
    default: throw new Error("Nieznany rozmiar");
  }
}

console.log(pobierzRozmiarKoszulki(2)); // "M"
try {
  pobierzRozmiarKoszulki(99);
} catch (e) {
  console.log(e.message); // "Nieznany rozmiar"
}

const PUNKTY_GPA = { A: 4.0, B: 3.0, C: 2.0, D: 1.0 };

function obliczOcenePunktowa(ocenaLiterowa) {
  return PUNKTY_GPA[ocenaLiterowa] ?? 0.0;
}

console.log(obliczOcenePunktowa("B")); // 3
console.log(obliczOcenePunktowa("F")); // 0

function przetworzKomende(komenda) {
  const log = [];
  switch (komenda) {
    case "start":
      log.push("Uruchamianie...");
      log.push("Gotowe");
      return { status: "dziala", log };
    case "stop":
      log.push("Zatrzymywanie...");
      return { status: "zatrzymany", log };
    default:
      return { status: "nieznana komenda", log };
  }
}

console.log(przetworzKomende("start")); // { status: 'dziala', log: ['Uruchamianie...', 'Gotowe'] }

const KOLORY_STATUSU = { aktywny: "zielony", wstrzymany: "zolty", zakonczony: "czerwony" };
console.log(Object.keys(KOLORY_STATUSU).includes("aktywny")); // true
console.log(Object.keys(KOLORY_STATUSU).includes("usuniety")); // false

function formatujOcene(procent) {
  switch (true) {
    case procent >= 90: return "A";
    case procent >= 80: return "B";
    case procent >= 70: return "C";
    case procent >= 60: return "D";
    default: return "F";
  }
}

console.log(formatujOcene(95)); // "A"
console.log(formatujOcene(55)); // "F"

const KONWERTERY_TEMPERATURY = {
  C_to_F: (c) => c * 9 / 5 + 32,
  F_to_C: (f) => (f - 32) * 5 / 9
};

function konwertuj(kierunek, wartosc) {
  return KONWERTERY_TEMPERATURY[kierunek](wartosc);
}

console.log(konwertuj("C_to_F", 20)); // 68
console.log(konwertuj("F_to_C", 68)); // 20

function sprawdzTypZmiennej(wartosc) {
  switch (typeof wartosc) {
    case "string": return "to string";
    case "number": return "to liczba";
    case "boolean": return "to boolean";
    default: return "inny typ";
  }
}

console.log(sprawdzTypZmiennej("tekst")); // "to string"
console.log(sprawdzTypZmiennej(42));      // "to liczba"
console.log(sprawdzTypZmiennej({}));      // "inny typ"

function obliczOplateWysylki(waga) {
  switch (true) {
    case waga <= 1: return 10;
    case waga <= 5: return 20;
    case waga <= 20: return 40;
    default: return 80;
  }
}

console.log(obliczOplateWysylki(1));  // 10
console.log(obliczOplateWysylki(3));  // 20
console.log(obliczOplateWysylki(50)); // 80

const KODY_HTTP = { 200: "OK", 404: "Nie znaleziono", 500: "Blad serwera" };
const para = Object.entries(KODY_HTTP).find(([k, v]) => v === "Nie znaleziono");
console.log(para); // ['404', 'Nie znaleziono']

function formatujDzienTygodnia(numer) {
  switch (numer) {
    case 1:
    case 2:
    case 3:
    case 4:
    case 5:
      return "Dzien roboczy";
    case 6:
    case 7:
      return "Weekend";
    default:
      return "Nieprawidlowy numer";
  }
}

console.log(formatujDzienTygodnia(3)); // "Dzien roboczy"
console.log(formatujDzienTygodnia(7)); // "Weekend"

const STRATEGIE_SORTOWANIA = {
  rosnaco: (a, b) => a - b,
  malejaco: (a, b) => b - a
};

const liczby = [3, 1, 4, 1, 5];
console.log([...liczby].sort(STRATEGIE_SORTOWANIA["malejaco"])); // [5, 4, 3, 1, 1]

function pobierzNazweKontynentu(kod) {
  switch (kod) {
    case "EU": return "Europa";
    case "NA": return "Ameryka Polnocna";
    case "AS": return "Azja";
    case "AF": return "Afryka";
    default: return "nieznany";
  }
}

console.log(pobierzNazweKontynentu("AS")); // "Azja"

const MNOZNIKI_JEDNOSTEK = { mm: 0.001, cm: 0.01, m: 1, km: 1000 };

function naMetry(wartosc, jednostka) {
  return wartosc * MNOZNIKI_JEDNOSTEK[jednostka];
}

console.log(naMetry(5, "km")); // 5000
console.log(naMetry(250, "cm")); // 2.5

function ocenPredkoscInternetu(mbps) {
  switch (true) {
    case mbps < 5: return "wolne";
    case mbps < 25: return "srednie";
    case mbps < 100: return "szybkie";
    default: return "bardzo szybkie";
  }
}

console.log(ocenPredkoscInternetu(3));   // "wolne"
console.log(ocenPredkoscInternetu(150)); // "bardzo szybkie"

